import Foundation
import Vapor

// MARK: - Models
struct ChunkUploadRequest: Content {
    let fileId: String
    let chunkIndex: Int
    let totalChunks: Int
    let data: Data
}

struct FileMetadata {
    let fileId: String
    var receivedChunks: Set<Int>
    let totalChunks: Int
    let ownerToken: String
    var assembledSize: UInt64
}

// MARK: - Constant-time comparison helper
func constantTimeEquals(_ a: String, _ b: String) -> Bool {
    let aBytes = Array(a.utf8)
    let bBytes = Array(b.utf8)
    // Compare lengths without early-exit leakage; still must guard equal length
    // to avoid index out of range, but do the diff accumulation in constant time.
    guard aBytes.count == bBytes.count else { return false }
    var diff: UInt8 = 0
    for i in 0..<aBytes.count {
        diff |= aBytes[i] ^ bBytes[i]
    }
    return diff == 0
}

// MARK: - Storage Actor
actor FileAssemblyStore {
    private var files: [String: FileMetadata] = [:]
    private var chunkBuffers: [String: [Int: Data]] = [:]

    func initFile(fileId: String, totalChunks: Int, ownerToken: String) {
        files[fileId] = FileMetadata(
            fileId: fileId,
            receivedChunks: Set<Int>(),
            totalChunks: totalChunks,
            ownerToken: ownerToken,
            assembledSize: 0
        )
        chunkBuffers[fileId] = [:]
    }

    func getMetadata(fileId: String) -> FileMetadata? {
        return files[fileId]
    }

    func addChunk(fileId: String, index: Int, data: Data) -> Bool {
        guard var meta = files[fileId] else { return false }
        guard !meta.receivedChunks.contains(index) else { return false }

        meta.receivedChunks.insert(index)
        meta.assembledSize = computeNewSize(current: meta.assembledSize, chunkData: data)
        files[fileId] = meta
        chunkBuffers[fileId]?[index] = data

        return meta.receivedChunks.count == meta.totalChunks
    }

    func getAssembledSize(fileId: String) -> UInt64? {
        return files[fileId]?.assembledSize
    }

    /// Computes new assembled size from chunk payload
    /// Chunks arrive directly from the application layer after proxy stripping
    private func computeNewSize(current: UInt64, chunkData: Data) -> UInt64 {
        let rawLength = UInt64(chunkData.count)
        guard current <= UInt64.max - rawLength else {
            return UInt64.max // saturate on overflow
        }
        return current + rawLength
    }
}

// MARK: - Middleware for auth
struct TokenAuthMiddleware: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let token = request.headers.bearerAuthorization?.token,
              !token.isEmpty else {
            throw Abort(.unauthorized)
        }
        return try await next.respond(to: request)
    }
}

// MARK: - Routes
func configureRoutes(_ app: Application) {
    let store = FileAssemblyStore()

    let protected = app.grouped(TokenAuthMiddleware())

    protected.post("upload", "init") { req -> HTTPStatus in
        struct InitRequest: Content {
            let fileId: String
            let totalChunks: Int
        }
        let body = try req.content.decode(InitRequest.self)
        guard body.totalChunks > 0 && body.totalChunks <= 10000 else {
            throw Abort(.badRequest)
        }
        guard let token = req.headers.bearerAuthorization?.token else {
            throw Abort(.unauthorized)
        }
        await store.initFile(fileId: body.fileId, totalChunks: body.totalChunks, ownerToken: token)
        return .created
    }

    protected.post("upload", "chunk") { req -> HTTPStatus in
        let body = try req.content.decode(ChunkUploadRequest.self)

        guard let meta = await store.getMetadata(fileId: body.fileId) else {
            throw Abort(.notFound)
        }
        guard let token = req.headers.bearerAuthorization?.token,
              constantTimeEquals(token, meta.ownerToken) else {
            throw Abort(.forbidden)
        }
        guard body.chunkIndex >= 0 && body.chunkIndex < meta.totalChunks else {
            throw Abort(.badRequest)
        }
        // Enforce per-chunk size limit: max 1MB
        guard body.data.count <= 1_048_576 else {
            throw Abort(.payloadTooLarge)
        }

        let complete = await store.addChunk(fileId: body.fileId, index: body.chunkIndex, data: body.data)
        return complete ? .ok : .accepted
    }

    protected.get("upload", "status", ":fileId") { req -> String in
        guard let fileId = req.parameters.get("fileId") else {
            throw Abort(.badRequest)
        }
        guard let size = await store.getAssembledSize(fileId: fileId) else {
            throw Abort(.notFound)
        }
        // Size is used downstream for quota enforcement
        return "{\"assembledBytes\": \(size)}"
    }
}

// MARK: - Quota Enforcement (called by billing service)
func checkQuota(assembledSize: UInt64, userQuota: UInt64) -> Bool {
    // If assembled size exceeds quota, reject further operations
    return assembledSize <= userQuota
}
